// machine stamps on its own heads that are NOT validation verdicts —
// sm-kicker fires on every non-main push, the runner wake-up probe and
// the Machine Merge Bot stamp their own bookkeeping. computePrStatus
// folds them out of the rollup; smAgent.js's gh-755 arm-time red-verdict
// probe (headHasRealFailure) skips the same set via this export so the
// two verdict readers can never drift apart.
var BOOKKEEPING_CHECK_PREFIXES = ['kicker /', 'Wake-up probe', 'merge /'];

// gh-807: machine verdict records (js/common/reviewVerdicts.js) ride the
// same ioCache as the other PR facts — the notLatestVerdict /
// latestVerdict guards may evaluate per rule per tick, and each would
// otherwise re-fetch the PR comment list (one github_get_pr_comments per
// guard evaluation; the memo collapses that to one per PR per tick).
//
// gh-823: the verdicts module is required at LOAD TIME, never lazily. A
// require executed after module init (any deferred/lazy call) resolves
// against the MAIN script's directory — the pack's js/ root — EXCLUSIVELY:
// the shipped lazy `require('./reviewVerdicts.js')` looked for
// js/reviewVerdicts.js and red every tick whose conflict-shaped queries
// screened an item ("state query failed: Failed to require module:
// ./reviewVerdicts.js") while ticks without candidates stayed green.
// Load-time requires resolve file-relative (js/common/reviewVerdicts.js —
// the module ships in every pack that carries smProvider.js, and dmtools
// compile discovers it here), so hoisting removes the deferred mode — the
// require can no longer run against a base where the module is absent.
// The ci require gate fails any release that reintroduces a deferred
// require in this module, and the pack runtime LOAD self-test loads it.
var reviewVerdicts = require('./reviewVerdicts.js');

// gh-1106: the workflows-permission rejection classifier — the same pure
// module the smAgent fork lane consumes, so the two silent-update paths
// (this provi…

/**
 * gh-1114 — SM tick layering: the rule-id → layer map for the deployed
 * sm_github.json tick, plus the merge-first capacity math.
 *
 * The SM tick runs in layers (relative order inside each layer = the
 * sm_github.json order):
 *
 *   L0 hygiene    rerun-cancelled-checks, rerun-any-cancelled-checks,
 *                 reconcile-*                          (no head moves)
 *   L1 freshness  unarm-stale-validation, silent-update-behind, park-reset
 *                 (heads may move here — silent branch refreshes)
 *   L2 verdict    merge-validated, fail-validation, rework-on-red-gate-unlatched,
 *                 rework-on-validation-failed, sweep-stale-validating
 *   L3 dispatch   validate-armed/-fresh/-masked-green, revalidate-armed(-green),
 *                 validated-green
 *   L4 agents     conflict-rework … review-on-issue-label
 *   L5 close      close-on-merge
 *
 * Freshness before verdicts: a head this tick's L1 rules moved carries no
 * checks yet, so an L2 verdict read against the superseded head is a false
 * verdict (live epam/dmtools-dart#435: fail-validation re-parked a PR on a
 * stale head seconds before silent-update-behind moved it). smAgent guards
 * the L2 actions with the tick's movedThisTick set and drops the openPrs
 * ioCache on the L1→L2 boundary so verdict queries read current heads.
 *
 * Merge-first capacity (owner directive 2026-10-19): one workflow slot
 * (jobParams.mergeReservedSlots, or the whole gh-837 parallel width) is
 * reserved for the approved merge path. L4 dispatch rules and fresh
 * validations may spend only cap − reserved until L3 has decided for the
 * merge candidate; an unused reservation is released to agent legs in the
 * same tick (no idle cap).
 *
 * UT-1 (gh-1114 AC6) pins this map against sm_github.json: every deployed
 * rule id must appear here with its layer, and the file order must be
 * non-decreasing by layer — adding a rule without registering it FAILS the
 * suite. Both the file and this map live in the same repo on purpose.
 *
 * GraalJS constraints: var declarations, plain functions, JSON-safe data.
