    var effBudget = (budgetCapped && workflowBudget)
        ? ruleBudgetRemaining(rule, workflowBudget) : null;
    if (effBudget !== null && effBudget <= 0) {
        var skippedLabel = rule.description || ('Rule #' + (ruleIndex + 1));
