    return !!(q.notLatestVerdict && lvVerdict &&
              q.notLatestVerdict.indexOf(lvVerdict) !== -1);
}

function _latestVerdictMiss(q, lvVerdict) {
    return !!(q.latestVerdict &&
              (!lvVerdict || q.latestVerdict.indexOf(lvVerdict) === -1));
}

