    // only when the rule actually filters on them.
    if (_prStatusFetchNeeded(q)) {
        items = _enrichPrItemsWithStatus(items, provider, repoInfo);
    }

    var matched = items.filter(function (item) {
        var labels = item.labels;
        var q2 = rule.query || {};
