            syncValidationChecks(effectiveRepoInfo, function (sha, st, co, url) {
                stampValidationChecksForModule(effectiveRepoInfo, sha, st, co, url);
            });
        } catch (e) {
            console.warn('  ⚠️  validation-check sync failed: ' + (e.message || e));
        }
