// control below can prove an unregistered rule FAILS it (AC6: 'adding a
// rule without a layer fails the test').
function layerOrderViolations(rules) {
    var violations = [];
    var lastIdx = -1;
    rules.forEach(function (r) {
        var idx = smRuleLayers.layerIndex(r);
        if (idx === -1) {
