    if (n.length > 60) n = n.substring(0, 60).trim();
    var l = String(login == null ? '' : login).replace(/[^A-Za-z0-9\-_\[\]]/g, '');
    if (!l) l = 'guest';
    return n + ' <' + l + '@' + NOREPLY_HOST + '>';
