/**
 * SM Provider — SCM-agnostic I/O for the machine-loop watchdog
 * (machineSmAgent.js).
 *
 * The watchdog's decision core is pure state → actions; this module is the
 * only place that talks to a forge. Provider selection mirrors scm.js:
 *
 *     var provider = createSmProvider({
 *         scm:    { provider: 'github' },           // 'github' | 'gitlab'
 *         repository: { owner: 'epam', repo: 'dmtools-dart' }
 *     });
 *
 * Everything goes through the unified snake_case tool surface (github_* /
 * gitlab_* MCP tools via the dmtools JS bridge) — the same abstraction the
 * rest of the agent ecosystem uses — so the watchdog runs unchanged on any
 * forge the bridge supports. The one exception today is GitHub's
 * update-branch (no native tool yet) which falls back to the gh CLI.
 *
 * Provider contract (all methods):
 *   listMachineIssues(machineLabels, agentHandle, limit) → [{number, title, labels, assignees}]
 *       Open issues carrying any machine label or the agent assignee.
 *   findPr(issueNumber, branchPrefix) → null | {number, state, branch}
 *       OPEN first (branch match <prefix><n> or body references #n), then
 *       MERGED on the branch (close-issue safety net).
 *   prStatus(prNumber) → {state, checkConclusion, mergeState, mergeable, author}
 *       checkConclusion: 'red' | 'green' | 'pending' | 'none'.
 *       author: creator login ('' when the API does not expose it) — the
 *       prMachineAuthor gate keys on it.
 *   activeMachineRuns() → [issueNumber, …]
 *       Issues with a queued/in_progress machine run right now.
 *   dispatchLeg(issueNumber, leg, reason)
 *       Fire the machine runner for that issue (leg: dev/review/rework).
 *   updateBranch(prNumber) / merge(prNumber) / closeIssue(n, comment)
 *   addIssueLabel(issueNumber, label)
 *
 * Known gaps (documented, non-fatal):
 *   - gitlab has no close-issue tool — closeIssue warns and no-ops.
 *   - gitlab activeMachineRuns cannot map a pipeline to an issue number
 *     (pipelines do not expose trigger variables) — any running API-sourced
 *     pipeline counts as "machine busy" (conservative: fewer parallel legs).
 *   - gitlab exposes no machine verdict records (gh-807: no MR-note reader
 *     in the tool catalog yet) — latestVerdictRecord is absent, so the
 *     latestVerdict/notLatestVerdict query guards never match/fail-open and
 *     the reconciliation stays GitHub-machine-loop behavior for now.
 */
'use strict';

// ── Per-tick I/O cache ────────────────────────────────────────────────────
// One TTL cache (60s) for the whole SM tick. Measured on a busy tick: the
// same open-PR list was re-fetched per rule AND per issue findPr (18
// github_list_prs calls returning the same payload in ONE tick). Routing
// the three list sites + prStatus through this cache collapses that to a
// single fetch per kind per repo. TTL hits change nothing observable —
// same payload, same 60s staleness budget as the old per-provider memo
// (the branchHead cache below), now shared across every provider instance
// created during the tick.
//
// runAsync workers are FRESH isolates with an empty module cache: they
// cannot see this holder. createSmProvider({ preseed }) re-hydrates it
// from an args-carried snapshot() bundle — the fan-out in
// sm/sources/githubSource.js ships the snapshot to each worker that way.
var SM_IO_CACHE_TTL_MS = 60 * 1000;
var _cache = { ttlMs: SM_IO_CACHE_TTL_MS, entries: {} };

function ioCacheKey(owner, repo, kind, id) {
    return owner + '/' + repo + ':' + kind + (id ? ':' + id : '');
}

function ioCacheGet(owner, repo, kind, id) {
    var key = ioCacheKey(owner, repo, kind, id);
    var entry = _cache.entries[key];
    if (!entry) return undefined;
    if (Date.now() - entry.at > _cache.ttlMs) {
        delete _cache.entries[key];
        return undefined;
    }
    return entry.data;
}

function ioCachePut(owner, repo, kind, id, data) {
    _cache.entries[ioCacheKey(owner, repo, kind, id)] = { at: Date.now(), data: data };
}

// Drop ONE cached entry (owner directive 2026-10-04 "red yields the slot"):
// the SM tick mutates PR labels mid-tick (fail_validation unarms
// ai_validating) and a LATER rule in the SAME tick must observe the freed
// mutex — validate-armed re-queries the open-PR list, which rides this
// cache. Without the drop the arm rule sees the stale arm and defers the
// whole approved FIFO to the next tick (live fa 2026-10-04 11:0x: #1194
// red, seven approved PRs queued 40+ min). Invalidate-after-mutation, not
// shorter TTLs: the 60s budget stays for read-only rules.
function ioCacheDrop(owner, repo, kind, id) {
    delete _cache.entries[ioCacheKey(owner, repo, kind, id)];
}

// Collect every non-expired entry of one kind for a repo into a plain
// {id: data} map — the prStatus leg of snapshot(). Keys are the id tail
// of the cache key (PR numbers as strings).
function ioCacheCollect(owner, repo, kind) {
    var out = {};
    var prefix = owner + '/' + repo + ':' + kind + ':';
    var keys = Object.keys(_cache.entries);
    for (var i = 0; i < keys.length; i++) {
        if (keys[i].indexOf(prefix) !== 0) continue;
        var entry = _cache.entries[keys[i]];
        if (Date.now() - entry.at > _cache.ttlMs) {
            delete _cache.entries[keys[i]];
            continue;
        }
        out[keys[i].substring(prefix.length)] = entry.data;
    }
    return out;
}

// Ecosystem-standard MCP result parsing (see parseMcpResult in the agent
// scripts): bridge tools may return decoded objects, JSON strings, or
// {data: …} envelopes.
function parseMcp(result) {
    if (!result) return null;
    if (typeof result === 'string') {
        try { return JSON.parse(result); } catch (e) { return null; }
    }
    return result;
}

function asList(parsed) {
    if (!parsed) return [];
    if (Array.isArray(parsed)) return parsed;
    if (Array.isArray(parsed.data)) return parsed.data;
    if (Array.isArray(parsed.pullRequests)) return parsed.pullRequests;
    if (Array.isArray(parsed.items)) return parsed.items;
    if (Array.isArray(parsed.issues)) return parsed.issues;
    return [];
}
// Bookkeeping check prefixes (dmtools-agents#628/#635): check runs the
// machine stamps on its own heads that are NOT validation verdicts —
// sm-kicker fires on every non-main push, the runner wake-up probe and
// the Machine Merge Bot stamp their own bookkeeping. computePrStatus
// folds them out of the rollup; smAgent.js's gh-755 arm-time red-verdict
// probe (headHasRealFailure) skips the same set via this export so the
// two verdict readers can never drift apart.
var BOOKKEEPING_CHECK_PREFIXES = ['kicker /', 'Wake-up probe', 'merge /'];

// gh-807: machine verdict records (js/common/reviewVerdicts.js) ride the
// same ioCache as the other PR facts — the notLatestVerdict /
// latestVerdict guards may evaluate per rule per tick, and each would
// otherwise re-fetch the PR comment list (one github_get_pr_comments per
// guard evaluation; the memo collapses that to one per PR per tick).
//
// gh-823: the verdicts module is required at LOAD TIME, never lazily. A
// require executed after module init (any deferred/lazy call) resolves
// against the MAIN script's directory — the pack's js/ root — EXCLUSIVELY:
// the shipped lazy `require('./reviewVerdicts.js')` looked for
// js/reviewVerdicts.js and red every tick whose conflict-shaped queries
// screened an item ("state query failed: Failed to require module:
// ./reviewVerdicts.js") while ticks without candidates stayed green.
// Load-time requires resolve file-relative (js/common/reviewVerdicts.js —
// the module ships in every pack that carries smProvider.js, and dmtools
// compile discovers it here), so hoisting removes the deferred mode — the
// require can no longer run against a base where the module is absent.
// The ci require gate fails any release that reintroduces a deferred
// require in this module, and the pack runtime LOAD self-test loads it.
var reviewVerdicts = require('./reviewVerdicts.js');

// gh-1106: the workflows-permission rejection classifier — the same pure
// module the smAgent fork lane consumes, so the two silent-update paths
// (this provi…

/**
 * gh-1114 — SM tick layering: the rule-id → layer map for the deployed
 * sm_github.json tick, plus the merge-first capacity math.
 *
 * The SM tick runs in layers (relative order inside each layer = the
 * sm_github.json order):
 *
 *   L0 hygiene    rerun-cancelled-checks, rerun-any-cancelled-checks,
 *                 reconcile-*                          (no head moves)
 *   L1 freshness  unarm-stale-validation, silent-update-behind, park-reset
 *                 (heads may move here — silent branch refreshes)
 *   L2 verdict    merge-validated, fail-validation, rework-on-red-gate-unlatched,
 *                 rework-on-validation-failed, sweep-stale-validating
 *   L3 dispatch   validate-armed/-fresh/-masked-green, revalidate-armed(-green),
 *                 validated-green
 *   L4 agents     conflict-rework … review-on-issue-label
 *   L5 close      close-on-merge
 *
 * Freshness before verdicts: a head this tick's L1 rules moved carries no
 * checks yet, so an L2 verdict read against the superseded head is a false
 * verdict (live epam/dmtools-dart#435: fail-validation re-parked a PR on a
 * stale head seconds before silent-update-behind moved it). smAgent guards
 * the L2 actions with the tick's movedThisTick set and drops the openPrs
 * ioCache on the L1→L2 boundary so verdict queries read current heads.
 *
 * Merge-first capacity (owner directive 2026-10-19): one workflow slot
 * (jobParams.mergeReservedSlots, or the whole gh-837 parallel width) is
 * reserved for the approved merge path. L4 dispatch rules and fresh
 * validations may spend only cap − reserved until L3 has decided for the
 * merge candidate; an unused reservation is released to agent legs in the
 * same tick (no idle cap).
 *
 * UT-1 (gh-1114 AC6) pins this map against sm_github.json: every deployed
 * rule id must appear here with its layer, and the file order must be
 * non-decreasing by layer — adding a rule without registering it FAILS the
 * suite. Both the file and this map live in the same repo on purpose.
 *
 * GraalJS constraints: var declarations, plain functions, JSON-safe data.
 */

var LAYER_ORDER = ['L0', 'L1', 'L2', 'L3', 'L4', 'L5'];

var LAYERS = {
    // L0 hygiene — cancelled-run kickers + verdict reconciliation (no head moves).
    'rerun-cancelled-checks': 'L0',
    'rerun-any-cancelled-checks': 'L0',
    'reconcile-rework-vs-approval': 'L0',
    'reconcile-issue-rework-vs-approval': 'L0',
    'reconcile-approval-vs-changes': 'L0',
    // L1 freshness — the only layer allowed to move a head.
    'unarm-stale-validation': 'L1',
    'silent-update-behind': 'L1',
    'park-reset': 'L1',
    // L2 verdict — merge/fail/arm/sweep on heads that did NOT move this tick.
    'merge-validated': 'L2',
    'merge-validated-guest': 'L2',
    'fail-validation': 'L2',
    'rework-on-red-gate-unlatched': 'L2',
    'rework-on-validation-failed': 'L2',
    'sweep-stale-validating': 'L2',
    // L3 dispatch — CI validation arms + the green latch.
    'validate-armed': 'L3',
    'revalidate-armed': 'L3',
    'revalidate-armed-green': 'L3',
    'validate-fresh': 'L3',
    'validate-fresh-masked-green': 'L3',
    'validated-green': 'L3',
    // L4 agents — rework/dev/review legs.
    'conflict-rework': 'L4',
    'rework-on-red-ci': 'L4',
    'rework-on-label': 'L4',
    'rework-arm-restore': 'L4',
    'dev-on-assignment': 'L4',
    'develop-done': 'L4',
    'review-after-dev': 'L4',
    'review-external-once': 'L4',
    'review-machine-unlinked': 'L4',
    'review-stale-verdict': 'L4',
    'review-threads-resolved': 'L4',
    'review-stale-verdict-unchecked': 'L4',
    'rework-unresolved-threads': 'L4',
    'review-on-label': 'L4',
    'review-on-issue-label': 'L4',
    // L5 close.
    'close-on-merge': 'L5'
};

// The L2 verdict actions (gh-1114 AC7): skipped for a PR whose head moved
// this tick. Keyed by localAction — rework-unresolved-threads (L4) shares
// arm_rework and defers with them, which invariant I5 states outright
// ('moved PR is never parked/reworked/commented in the same tick').
var VERDICT_DEFER_ACTIONS = ['merge_pr', 'fail_validation', 'arm_rework', 'sweep_stale_validation'];

// Layer indexes (numeric) used for the boundary checks.
var L1_IDX = LAYER_ORDER.indexOf('L1');
var L3_IDX = LAYER_ORDER.indexOf('L3');

function layerOf(rule) {
    var id = rule && rule.id;
    return (id && LAYERS[id]) || null;
}

// Numeric layer index of a rule, or -1 for a rule the map does not know
// (jira rules, custom project smRules) — unknown rules never trigger a
// layer transition and are never merge-path.
function layerIndex(rule) {
    var layer = layerOf(rule);
    return layer === null ? -1 : LAYER_ORDER.indexOf(layer);
}

function isVerdictAction(rule) {
    return !!rule && VERDICT_DEFER_ACTIONS.indexOf(rule.localAction) !== -1;
}

// Merge-path rules — the only dispatch lanes allowed to spend the reserved
// capacity slot (and the only validations deferred for a head moved this
// tick, AC12):
//   - the approved merge-window arms (validate-armed + the revalidate
//     recovery twins — detected structurally so project-config clones of
//     these rules keep the property);
//   - rework-on-red-ci: a rework leg on an approved PR whose validation
//     went red is a merge-path leg (owner directive 2026-10-19) — it goes
//     before review/dev legs of non-approved PRs when the budget is short.
function isMergePathRule(rule) {
    if (!rule) return false;
    if (rule.id === 'rework-on-red-ci') return true;
    if (rule.localAction === 'validate_pr') {
        var q = rule.query || {};
        return q.mutex === 'ai_validating' &&
            Array.isArray(q.mutexAmong) &&
            q.mutexAmong.indexOf('pr_approved') !== -1;
    }
    return false;
}

// The string spelling of jobParams.mergeReservedSlots (repo variables arrive
// as strings): 'false' disables, any other value parses as an integer
// (unparsable → NaN → junk). Callers treat a non-positive result as disabled.
function parseReservedSlotsString(raw) {
    var trimmed = raw.trim();
    if (trimmed === 'false') return 0;
    return parseInt(trimmed, 10);
}

// Coerces jobParams.mergeReservedSlots to its numeric slot count, or null
// when the value is unset or junk (anything that is not a usable count:
// booleans map to 1/0, strings parse, NaN and non-numbers are junk).
function reservedSlotsValue(jobParams) {
    var raw = (jobParams || {}).mergeReservedSlots;
    if (typeof raw === 'string') raw = parseReservedSlotsString(raw);
    if (typeof raw === 'number' && !isNaN(raw)) return Math.floor(raw);
    if (typeof raw === 'boolean') return raw ? 1 : 0;
    return null;
}

// jobParams.mergeReservedSlots — the merge-path reservation, default 1.
// 0 / false (or the string 'false') disables the reservation (bit-identical
// with the pre-gh-1114 capacity behavior).
function mergeReservedSlots(jobParams) {
    var slots = reservedSlotsValue(jobParams);
    if (slots !== null) return slots > 0 ? slots : 0;
    var raw = (jobParams || {}).mergeReservedSlots;
    return raw == null ? 1 : 0; // unset (or null) → default; junk disables rather than guess
}

// The reservation width for the tick: the whole gh-837 parallel width when
// parallel validation is active (queue ≥ watermark), else mergeReservedSlots.
// An EXPLICIT disable (slots <= 0) wins in every mode — mergeReservedSlots
// documents 0/false as the kill switch ("bit-identical with the pre-gh-1114
// capacity behavior"), so the parallel override must never resurrect the
// reservation (PR #1120 review, thread smRuleLayers.js:167).
function reservationFor(mergeSlots, validationMutexMax) {
    var slots = mergeSlots || 0;
    if (slots <= 0) return 0;
    var mutexMax = validationMutexMax || 1;
    return mutexMax > 1 ? mutexMax : slots;
}

module.exports = {
    LAYER_ORDER: LAYER_ORDER,
    LAYERS: LAYERS,
    VERDICT_DEFER_ACTIONS: VERDICT_DEFER_ACTIONS,
    L1_IDX: L1_IDX,
    L3_IDX: L3_IDX,
    layerOf: layerOf,
    layerIndex: layerIndex,
    isVerdictAction: isVerdictAction,
    isMergePathRule: isMergePathRule,
    mergeReservedSlots: mergeReservedSlots,
    reservationFor: reservationFor
};

/**
 * Guest validation path (gh-113) — the pure half of the guest-PR
 * dead-zone fixes.
 *
 * Live shape (IstiN/flutter_agent_harness, 2026-10-19, PRs #1634/#1615/#1591):
 * guest PRs from a fork sat APROVED + CLEAN + behind=0 for hours with a
 * MANUAL ai_validating label and never merged. Three facts compound:
 *
 *   1. The validation dispatch is fork-blind: `workflow_dispatch` with
 *      `ref: <fork-branch>` answers 422 on the base repo (gh-1075 fixed
 *      the AI-leg lane; the validate_pr lane stays branch-targeted), so
 *      no real validation run is ever dispatched on a guest head.
 *   2. The guest heads carry only the merge bot's SKIPPED stub checks
 *      ('merge / …'). The smProvider ROLLUP label deliberately reads
 *      'pending' for such a head (bookkeeping checks are "no verdict
 *      yet" — that label arms validate-fresh), so merge-validated
 *      (checks: green) never matches either.
 *   3. The red re-validation lane (rework-on-validation-failed) is
 *      machine-author-only, so a stale validation_failed park on a
 *      guest has no self-clear twin of gh-750.
 *
 * The owner-sanctioned policy this module implements: a MANUAL
 * ai_validating label on a guest PR is an EXTERNAL VALIDATION ARM —
 * the human vouches for the head — so the merge lane may treat a
 * zero-failing check rollup (no real red, no real in-flight check;
 * bookkeeping stubs and CANCELLED runs are not verdicts) as green for
 * guests, and the park ladder gains a guest rung that clears a stale
 * validation_failed when the punished head carries no red of its own.
 *
 * Exports:
 *   realCheckTally(checkRuns, bookeepingPrefixes) — the REAL check-run
 *       census { red, pending, real, bokept, canceled }. Deliberately
 *       NOT the smProvider rollup semantics: bookkeeping-only heads
 *       tally zero real checks here (the merge-side policy), while the
 *       rollup label reads 'pending' for them (the arming-side policy).
 *   mergeableZeroFailing(tally) — merge bar: red === 0 && pending === 0.
 *       A real in-flight check owns the verdict — never merge ahead of
 *       it. Degraded input (null) fails closed.
 *   recoverableZeroRed(tally) — park-recovery bar: the head is decided
 *       (real >= 1, the fa#923 undecided-head guard) and red === 0. A
 *       real in-flight run is not red; its verdict re-parks a genuinely
 *       red head one cycle later. Degraded input fails closed.
 *   newestArmEvent(events) — the newest `labeled` event for
 *       ai_validating from an issue-events feed (chronological, so the
 *       LAST match wins); null when the feed carries none.
 *   isManualArm(armEvent, machineAuthor) — the external-arm test: the
 *       event exists and its actor is NOT a machine login (the gh-728
 *       comma-separated knob, gh-1025 [bot]-suffix normalization). No
 *       event → false (fail closed — an irreversible merge needs the
 *       proof). No machineAuthor configured → every actor is external
 *       (a deployment without the knob has no machine identity at all).
 *   blockedGuestEntry(item, pr, isGuest) — the dead-zone shape: guest +
 *       (pr_approved | ai_validating) + CLEAN + rollup none|pending.
 *       Returns the summary entry or null. A failed/absent status probe
 *       (pr === null) is NEVER counted (fail closed).
 *   mergeDeadZoneCary(prev, current) — the cross-tick carry for the
 *       factory-state snapshot: per-PR first-seen timestamps (age never
 *       resets while a guest stays blocked); guests that stopped being
 *       blocked drop out.
