        if (idx < lastIdx) {
            violations.push(r.id + ' (layer ' + smRuleLayers.layerOf(r) +
                ') runs after a later-layer rule — the layer order is violated');
        }
        lastIdx = Math.max(lastIdx, idx);
    });
    return violations;
}

