    var b = String(branch || '');
    var p = String(branchPrefix || '');
    if (!b || !p || b.indexOf(p) !== 0) return null;
    var tail = b.substring(p.length);
    return /^\d+$/.test(tail) ? parseInt(tail, 10) : null;
}

