    t = t.replace(/[\x00-\x1f\x7f\r\n\t]+/g, ' ');
    t = t.replace(/\s+/g, ' ').trim();
    if (t.length > cap) t = t.substring(0, cap).trim();
    return t;
}

function sanitizeCoAuthor(name, login) {
    var n = String(name == null ? '' : name)
