    label: 'po_accept',
    parkedLabel: 'blocked',
    branchPrefix: 'ai/guest-',
    baseBranch: 'main',
    titlePrefix: '[guest #{N}]',
    carryLabels: ['ai_pr_reviewed', 'pr_approved'],
    titleMaxLen: 80,
    gateJobs: ['security-gate'],
    secretJobs: ['validate']
};

var NOREPLY_HOST = 'users.noreply.github.com';
var SHA_RE = /^[0-9a-f]{40}$/;

function strOr(v, dflt) {
    return (typeof v === 'string' && v) ? v : dflt;
