    parkedLabel: 'blocked',
    branchPrefix: 'ai/guest-',
    baseBranch: 'main',
    titlePrefix: '[guest #{N}]',
    carryLabels: ['ai_pr_reviewed', 'pr_approved'],
    titleMaxLen: 80,
    gateJobs: ['security-gate'],
    secretJobs: ['validate']
