function isCrossRepoHead(headFull, owner, repo) {
    if (typeof headFull !== 'string' || headFull.indexOf('/') === -1) return false;
    var parts = headFull.split('/');
    if (parts.length !== 2 || !parts[0] || !parts[1]) return false;
