    var body = sanitizeGuestTitle(title, (cfg && cfg.titleMaxLen) || DEFAULTS.titleMaxLen);
    var rest = body || 'guest change';
    var cap = (cfg && cfg.titleMaxLen) || DEFAULTS.titleMaxLen;
