    function forkPrsFixture() {
        return [
            { number: 401, state: 'open', draft: false, body: '',
              head: { sha: 'a1', ref: 'patch-1', repo: { full_name: 'extc/fork' } },
              labels: [{ name: 'po_accept' }], user: { login: 'extc' } },
